package auth

import (
	"context"
	"fmt"
	"strings"

	"go.flipt.io/flipt/internal/server/audit"
	"go.flipt.io/flipt/internal/storage"
	storageauth "go.flipt.io/flipt/internal/storage/auth"
	"go.flipt.io/flipt/rpc/flipt/auth"
	"go.uber.org/zap"
	"google.golang.org/grpc"
	"google.golang.org/grpc/metadata"
	"google.golang.org/protobuf/types/known/emptypb"
	"google.golang.org/protobuf/types/known/timestamppb"
)

const ipKey = "x-forwarded-for"

var _ auth.AuthenticationServiceServer = &Server{}

// Actor represents some metadata from the context for the audit event.
type Actor map[string]string

func ActorFromContext(ctx context.Context) Actor {
	var (
		actor          = Actor{}
		authentication = "none"
	)

	md, _ := metadata.FromIncomingContext(ctx)
	if len(md[ipKey]) > 0 {
		actor["ip"] = md[ipKey][0]
	}

	auth := GetAuthenticationFrom(ctx)
	if auth != nil {
		authentication = strings.ToLower(strings.TrimPrefix(auth.Method.String(), "METHOD_"))
		for k, v := range auth.Metadata {
			actor[k] = v
		}
	}

	actor["authentication"] = authentication
	return actor
}

// Server is the core AuthenticationServiceServer implementations.
//
// It is the service which presents all Authentications created in the backing auth store.
type Server struct {
	logger *zap.Logger
	store  storageauth.Store

	enableAuditLogging bool

	auth.UnimplementedAuthenticationServiceServer
}

type Option func(*Server)

// WithAuditLoggingEnabled sets the option for enabling audit logging for the auth server.
func WithAuditLoggingEnabled(enabled bool) Option {
	return func(s *Server) {
		s.enableAuditLogging = enabled
	}
}

func NewServer(logger *zap.Logger, store storageauth.Store, opts ...Option) *Server {
	s := &Server{
		logger: logger,
		store:  store,
	}

	for _, opt := range opts {
		opt(s)
	}

	return s
}

// RegisterGRPC registers the server as an Server on the provided grpc server.
func (s *Server) RegisterGRPC(server *grpc.Server) {
	auth.RegisterAuthenticationServiceServer(server, s)
}

// GetAuthenticationSelf returns the Authentication which was derived from the request context.
func (s *Server) GetAuthenticationSelf(ctx context.Context, _ *emptypb.Empty) (*auth.Authentication, error) {
	if auth := GetAuthenticationFrom(ctx); auth != nil {
		s.logger.Debug("GetAuthentication", zap.String("id", auth.Id))

		return auth, nil
	}

	return nil, errUnauthenticated
}

// GetAuthentication returns the Authentication identified by the supplied id.
func (s *Server) GetAuthentication(ctx context.Context, r *auth.GetAuthenticationRequest) (*auth.Authentication, error) {
	return s.store.GetAuthenticationByID(ctx, r.Id)
}

// ListAuthentications produces a set of authentications for the provided method filter and pagination parameters.
func (s *Server) ListAuthentications(ctx context.Context, r *auth.ListAuthenticationsRequest) (*auth.ListAuthenticationsResponse, error) {
	req := &storage.ListRequest[storageauth.ListAuthenticationsPredicate]{
		QueryParams: storage.QueryParams{
			Limit:     uint64(r.Limit),
			PageToken: r.PageToken,
		},
	}

	if r.Method != auth.Method_METHOD_NONE {
		req.Predicate.Method = &r.Method
	}

	results, err := s.store.ListAuthentications(ctx, req)
	if err != nil {
		s.logger.Error("listing authentication", zap.Error(err))

		return nil, fmt.Errorf("listing authentications: %w", err)
	}

	return &auth.ListAuthenticationsResponse{
		Authentications: results.Results,
		NextPageToken:   results.NextPageToken,
	}, nil
}

// DeleteAuthentication deletes the authentication with the supplied ID.
func (s *Server) DeleteAuthentication(ctx context.Context, req *auth.DeleteAuthenticationRequest) (*emptypb.Empty, error) {
	s.logger.Debug("DeleteAuthentication", zap.String("id", req.Id))

	if s.enableAuditLogging {
		actor := ActorFromContext(ctx)

		a, err := s.GetAuthentication(ctx, &auth.GetAuthenticationRequest{
			Id: req.Id,
		})
		if err != nil {
			s.logger.Error("failed to get authentication for audit events", zap.Error(err))
			return nil, err
		}
		if a.Method == auth.Method_METHOD_TOKEN {
			event := audit.NewEvent(audit.TokenType, audit.Delete, actor, a.Metadata)
			event.AddToSpan(ctx)
		}
	}

	return &emptypb.Empty{}, s.store.DeleteAuthentications(ctx, storageauth.Delete(storageauth.WithID(req.Id)))
}

// ExpireAuthenticationSelf expires the Authentication which was derived from the request context.
// If no expire_at is provided, the current time is used. This is useful for logging out a user.
// If the expire_at is greater than the current expiry time, the expiry time is extended.
func (s *Server) ExpireAuthenticationSelf(ctx context.Context, req *auth.ExpireAuthenticationSelfRequest) (*emptypb.Empty, error) {
	if auth := GetAuthenticationFrom(ctx); auth != nil {
		s.logger.Debug("ExpireAuthentication", zap.String("id", auth.Id))

		if req.ExpiresAt == nil || !req.ExpiresAt.IsValid() {
			req.ExpiresAt = timestamppb.Now()
		}

		return &emptypb.Empty{}, s.store.ExpireAuthenticationByID(ctx, auth.Id, req.ExpiresAt)
	}

	return nil, errUnauthenticated
}
	}
}

// EventPairChecker is the middleware side contract for checking if an event pair exists.
type EventPairChecker interface {
	Check(eventPair string) bool
}

// AuditUnaryInterceptor sends audit logs to configured sinks upon successful RPC requests for auditable events.
func AuditUnaryInterceptor(logger *zap.Logger, eventPairChecker EventPairChecker) grpc.UnaryServerInterceptor {
	return func(ctx context.Context, req interface{}, info *grpc.UnaryServerInfo, handler grpc.UnaryHandler) (interface{}, error) {
		resp, err := handler(ctx, req)
		if err != nil {
			return resp, err
		}

		actor := auth.ActorFromContext(ctx)

		var event *audit.Event

		defer func() {
			if event != nil {
				ts := string(event.Type)
				as := string(event.Action)
				eventPair := fmt.Sprintf("%s:%s", ts, as)

				exists := eventPairChecker.Check(eventPair)
				if exists {
					span := trace.SpanFromContext(ctx)
					span.AddEvent("event", trace.WithAttributes(event.DecodeToAttributes()...))
				}
			}
		}()

		// Delete request(s) have to be handled separately because they do not
		// return the concrete type but rather an *empty.Empty response.
		switch r := req.(type) {
		case *flipt.DeleteFlagRequest:
			event = audit.NewEvent(audit.FlagType, audit.Delete, actor, r)
		case *flipt.DeleteVariantRequest:
			event = audit.NewEvent(audit.VariantType, audit.Delete, actor, r)
		case *flipt.DeleteSegmentRequest:
			event = audit.NewEvent(audit.SegmentType, audit.Delete, actor, r)
		case *flipt.DeleteDistributionRequest:
			event = audit.NewEvent(audit.DistributionType, audit.Delete, actor, r)
		case *flipt.DeleteConstraintRequest:
			event = audit.NewEvent(audit.ConstraintType, audit.Delete, actor, r)
		case *flipt.DeleteNamespaceRequest:
			event = audit.NewEvent(audit.NamespaceType, audit.Delete, actor, r)
		case *flipt.DeleteRuleRequest:
			event = audit.NewEvent(audit.RuleType, audit.Delete, actor, r)
		case *flipt.DeleteRolloutRequest:
			event = audit.NewEvent(audit.RolloutType, audit.Delete, actor, r)
		}

		// Short circuiting the middleware here since we have a non-nil event from
		// detecting a delete.
		if event != nil {
			return resp, err
		}

		action := audit.GRPCMethodToAction(info.FullMethod)

		switch r := resp.(type) {
		case *flipt.Flag:
			if action != "" {
				event = audit.NewEvent(audit.FlagType, action, actor, audit.NewFlag(r))
			}
		case *flipt.Variant:
			if action != "" {
				event = audit.NewEvent(audit.VariantType, action, actor, audit.NewVariant(r))
			}
		case *flipt.Segment:
			if action != "" {
				event = audit.NewEvent(audit.SegmentType, action, actor, audit.NewSegment(r))
			}
		case *flipt.Distribution:
			if action != "" {
				event = audit.NewEvent(audit.DistributionType, action, actor, audit.NewDistribution(r))
			}
		case *flipt.Constraint:
			if action != "" {
				event = audit.NewEvent(audit.ConstraintType, action, actor, audit.NewConstraint(r))
			}
		case *flipt.Namespace:
			if action != "" {
				event = audit.NewEvent(audit.NamespaceType, action, actor, audit.NewNamespace(r))
			}
		case *flipt.Rollout:
			if action != "" {
				event = audit.NewEvent(audit.RolloutType, action, actor, audit.NewRollout(r))
			}
		case *flipt.Rule:
			if action != "" {
				event = audit.NewEvent(audit.RuleType, action, actor, audit.NewRule(r))
			}
		case *fauth.CreateTokenResponse:
			event = audit.NewEvent(audit.TokenType, audit.Create, actor, r.Authentication.Metadata)
		}

		return resp, err
	}
}

type namespaceKeyer interface {
	GetNamespaceKey() string
}

type flagKeyer interface {
	namespaceKeyer
	GetKey() string
}

type variantFlagKeyger interface {
	namespaceKeyer
	GetFlagKey() string
}

func flagCacheKey(namespaceKey, key string) string {
	// for backward compatibility
	if namespaceKey != "" {
		return fmt.Sprintf("f:%s:%s", namespaceKey, key)
	}
	return fmt.Sprintf("f:%s", key)
}

type evaluationRequest interface {
	GetNamespaceKey() string
	GetFlagKey() string
	GetEntityId() string
	GetContext() map[string]string
	// forward internal gRPC logging to zap
	grpcLogLevel, err := zapcore.ParseLevel(cfg.Log.GRPCLevel)
	if err != nil {
		return nil, fmt.Errorf("parsing grpc log level (%q): %w", cfg.Log.GRPCLevel, err)
	}

	grpc_zap.ReplaceGrpcLoggerV2(logger.WithOptions(zap.IncreaseLevel(grpcLogLevel)))

	// add auth interceptors to the server
	interceptors = append(interceptors,
		append(authInterceptors,
			middlewaregrpc.ErrorUnaryInterceptor,
			middlewaregrpc.ValidationUnaryInterceptor,
			middlewaregrpc.EvaluationUnaryInterceptor,
		)...,
	)

	// cache must come after auth interceptors
	if cfg.Cache.Enabled && cacher != nil {
		interceptors = append(interceptors, middlewaregrpc.CacheUnaryInterceptor(cacher, logger))
	}

	// audit sinks configuration
	sinks := make([]audit.Sink, 0)

	if cfg.Audit.Sinks.LogFile.Enabled {
		logFileSink, err := logfile.NewSink(logger, cfg.Audit.Sinks.LogFile.File)
		if err != nil {
			return nil, fmt.Errorf("opening file at path: %s", cfg.Audit.Sinks.LogFile.File)
		}

		sinks = append(sinks, logFileSink)
	}

	if cfg.Audit.Sinks.Webhook.Enabled {
		opts := []webhook.ClientOption{}
		if cfg.Audit.Sinks.Webhook.MaxBackoffDuration != 0 {
			opts = append(opts, webhook.WithMaxBackoffDuration(cfg.Audit.Sinks.Webhook.MaxBackoffDuration))
		}

		webhookSink := webhook.NewSink(logger, webhook.NewHTTPClient(logger, cfg.Audit.Sinks.Webhook.URL, cfg.Audit.Sinks.Webhook.SigningSecret, opts...))

		sinks = append(sinks, webhookSink)
	}

	// based on audit sink configuration from the user, provision the audit sinks and add them to a slice,
	// and if the slice has a non-zero length, add the audit sink interceptor
	if len(sinks) > 0 {
		checker, err := audit.NewChecker(cfg.Audit.Events)
		if err != nil {
			return nil, err
		}

		sse := audit.NewSinkSpanExporter(logger, sinks)
		tracingProvider.RegisterSpanProcessor(tracesdk.NewBatchSpanProcessor(sse, tracesdk.WithBatchTimeout(cfg.Audit.Buffer.FlushPeriod), tracesdk.WithMaxExportBatchSize(cfg.Audit.Buffer.Capacity)))

		interceptors = append(interceptors, middlewaregrpc.AuditUnaryInterceptor(logger, checker))
		logger.Debug("audit sinks enabled",
			zap.Stringers("sinks", sinks),
			zap.Int("buffer capacity", cfg.Audit.Buffer.Capacity),
			zap.String("flush period", cfg.Audit.Buffer.FlushPeriod.String()),
			zap.Strings("events", checker.Events()),
		)

		server.onShutdown(func(ctx context.Context) error {
			return sse.Shutdown(ctx)
		})
	}

	server.onShutdown(func(ctx context.Context) error {
		return tracingProvider.Shutdown(ctx)
	})

	otel.SetTracerProvider(tracingProvider)
	otel.SetTextMapPropagator(propagation.NewCompositeTextMapPropagator(propagation.TraceContext{}, propagation.Baggage{}))

	grpcOpts := []grpc.ServerOption{grpc.ChainUnaryInterceptor(interceptors...)}

	if cfg.Server.Protocol == config.HTTPS {
		creds, err := credentials.NewServerTLSFromFile(cfg.Server.CertFile, cfg.Server.CertKey)
		if err != nil {
			return nil, fmt.Errorf("loading TLS credentials: %w", err)
		}

		grpcOpts = append(grpcOpts, grpc.Creds(creds))
	}

	// initialize grpc server
	server.Server = grpc.NewServer(grpcOpts...)

	// register grpcServer graceful stop on shutdown
package cmd

